-- workflow-engine (platform, default autonomy auto)

-- PII registries: worker roles, matched by app.current_actor_role() (0027).
UPDATE app.pii_column SET collect_roles = collect_roles || ARRAY['worker_employee_record_writer', 'worker_new_hire_doc_collector']::text[] WHERE table_name = 'employee' AND column_name = 'aadhaar_ekyc_ref';
UPDATE app.pii_column SET collect_roles = collect_roles || ARRAY['worker_employee_record_writer']::text[] WHERE table_name = 'employee' AND column_name = 'bank_account_encrypted';
UPDATE app.pii_column SET collect_roles = collect_roles || ARRAY['worker_employee_record_writer', 'worker_new_hire_doc_collector']::text[] WHERE table_name = 'employee' AND column_name = 'pan_encrypted';
UPDATE app.pii_column SET collect_roles = collect_roles || ARRAY['worker_employee_record_writer', 'worker_new_hire_doc_collector']::text[] WHERE table_name = 'employee' AND column_name = 'ssn_encrypted';
UPDATE app.pii_purpose SET allowed_roles = allowed_roles || ARRAY['worker_background_check_initiator']::text[] WHERE purpose = 'background_check';
UPDATE app.pii_purpose SET allowed_roles = allowed_roles || ARRAY['worker_employee_record_writer', 'worker_i9_e_verify_initiator', 'worker_new_hire_doc_collector']::text[] WHERE purpose = 'identity_verification';
UPDATE app.pii_purpose SET allowed_roles = allowed_roles || ARRAY['worker_direct_deposit_disburser']::text[] WHERE purpose = 'payroll_disbursal';
UPDATE app.pii_purpose SET allowed_roles = allowed_roles || ARRAY['worker_tax_filing_submitter']::text[] WHERE purpose = 'tax_filing';

RESET ROLE;
